using ApiFromLecture.Models;using Microsoft.AspNetCore.Mvc; namespace ApiFromLecture.Controllers; [ApiController][Route("api/validation")]public class ValidationController:ControllerBase{[HttpPost("register")]public IActionResult Register(RegisterRequest r)=>Ok(r);[HttpPost("event")]public IActionResult Event(EventRequest r)=>Ok(r);[HttpPost("date-range")]public IActionResult Range(DateRangeRequest r)=>Ok(r);[HttpPost("order")]public IActionResult Order(OrderRequest r)=>Ok(r);[HttpGet("model-state")]public IActionResult ModelStateExample(){ModelState.AddModelError("Name","Имя уже занято");return ValidationProblem(ModelState);}[HttpGet("not-found/{id:int}")]public IActionResult NotFoundExample(int id)=>Problem(title:"Product not found",detail:$"Product with id {id} does not exist",statusCode:404,type:"https://example.com/errors/not-found");[HttpGet("conflict")]public IActionResult Conflict(){var p=new ProblemDetails{Status=409,Title="Conflict",Detail="Product with this name already exists",Instance=HttpContext.Request.Path};p.Extensions["traceId"]=HttpContext.TraceIdentifier;return new ObjectResult(p){StatusCode=409};}[HttpGet("exception")]public IActionResult Exception()=>throw new KeyNotFoundException("Product with id 42 does not exist");}
